const SHELL_CSS = `
  :root{
    --ink:#12213b; --ink-soft:#1d3258; --fog:#f3f5f9; --line:#d3dae6; --steel:#56657e;
    --hl:#ffd93d; --danger:#b3261e; --danger-bg:#fdecea;
    --ok:#075e4b; --ok-bg:#d4f0e6;
    --display:'Bricolage Grotesque','Segoe UI',system-ui,sans-serif;
    --body:'Instrument Sans',system-ui,-apple-system,'Segoe UI',sans-serif;
  }
  *{box-sizing:border-box}
  body{margin:0;background:var(--fog);color:var(--ink);font-family:var(--body);font-size:16px;line-height:1.5;-webkit-font-smoothing:antialiased}
  button{font:inherit;color:inherit}
  a{color:var(--ink)}
  .bar{background:#fff;border-bottom:1px solid var(--line)}
  .bar__in{display:flex;align-items:center;height:64px;padding:0 40px}
  .brand{display:inline-flex;align-items:center;gap:10px;font-family:var(--display);font-weight:700;font-size:20px;letter-spacing:-.02em}
  .brand svg{width:32px;height:32px}
  main{padding:48px 40px 80px}
  .crumb{font-size:14px;margin:0 0 12px}
  .crumb a{color:var(--steel);text-decoration:none}
  h1{margin:0 0 8px;font-family:var(--display);font-size:40px;font-weight:700;line-height:1.1;letter-spacing:-.03em}
  h2{margin:0;font-family:var(--display);font-size:20px;font-weight:700;letter-spacing:-.02em}
  .lede{margin:0 0 32px;font-size:17px;color:var(--steel)}
  .lede strong{color:var(--ink)}
  .figures{display:flex;flex-wrap:wrap;margin:0 0 40px;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}
  .figures div{flex:1 1 140px;padding:18px 0 18px 22px;border-left:1px solid var(--line)}
  .figures div:first-child{padding-left:0;border-left:0}
  .figures dt{font-size:13px;color:var(--steel)}
  .figures dd{margin:2px 0 0;font-family:var(--display);font-size:30px;font-weight:700;letter-spacing:-.02em;font-variant-numeric:tabular-nums}
  .panel{background:#fff;border:1px solid var(--line);border-top:4px solid var(--c, var(--hl));border-radius:12px;padding:26px 28px 24px;margin-bottom:24px}
  .panel__head{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:6px;flex-wrap:wrap}
  .panel__title{display:flex;align-items:center;gap:12px}
  .panel__right{display:flex;align-items:center;gap:14px;flex-wrap:wrap}
  .dot{width:10px;height:10px;border-radius:50%;background:var(--c, var(--hl));flex:none}
  .count{font-size:14px;color:var(--steel)}
  .count b{color:var(--ink)}
  .hint{font-size:14px;color:var(--steel);margin:0 0 16px}
  .tablewrap{overflow-x:auto}
  table{width:100%;border-collapse:collapse;font-size:14px}
  th{padding:10px 12px;background:var(--fog);color:var(--steel);font-weight:600;text-align:left;white-space:nowrap}
  th:first-child{border-radius:8px 0 0 8px} th:last-child{border-radius:0 8px 8px 0}
  td{padding:14px 12px;border-bottom:1px solid var(--line);vertical-align:top}
  tr:last-child td{border-bottom:0}
  tbody tr:hover td{background:#fafbfd}
  .name{font-weight:700;font-size:15px}
  .muted{font-size:13px;color:var(--steel)}
  .score{font-family:var(--display);font-size:18px;font-weight:700;font-variant-numeric:tabular-nums}
  .summary{max-width:320px;font-size:13px;color:var(--steel);line-height:1.5}
  .link{display:inline-flex;align-items:center;height:30px;padding:0 10px;border-radius:6px;background:var(--fog);color:var(--ink);font-size:13px;font-weight:600;text-decoration:none;white-space:nowrap}
  .link:hover{background:#e8ecf3}
  .tag{display:inline-block;padding:3px 10px;border-radius:999px;background:var(--fog);color:var(--steel);font-size:12px;font-weight:600;white-space:nowrap}
  .actions{display:flex;gap:6px;flex-wrap:wrap}
  .btn{height:36px;padding:0 14px;border:0;border-radius:8px;font-size:14px;font-weight:600;cursor:pointer;background:var(--ok);color:#fff;white-space:nowrap}
  .btn:hover:not(:disabled){background:#05503f}
  .btn:disabled{opacity:.55;cursor:wait}
  .btn-alt{background:#fff;color:var(--ink);border:1.5px solid var(--ink)}
  .btn-alt:hover:not(:disabled){background:var(--ink);color:#fff}
  .empty{padding:24px;border:1px dashed var(--line);border-radius:12px;text-align:center;color:var(--steel);font-size:15px}
  @media (max-width:860px){h1{font-size:32px}.figures div{padding-left:16px}}
  @media (max-width:560px){main{padding:32px 16px 56px}.bar__in{padding:0 16px}.panel{padding:20px 16px 18px}}
`;

const shell = (title, body) => `<!DOCTYPE html>
<html lang="en"><head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${title} - Shortlist</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:opsz,wght@12..96,500..800&family=Instrument+Sans:wght@400..700&display=swap" rel="stylesheet">
<style>${SHELL_CSS}</style></head><body>
<header class="bar"><div class="bar__in">
  <span class="brand">
    <svg viewBox="0 0 32 32" aria-hidden="true">
      <rect width="32" height="32" rx="8" fill="#12213B"/>
      <rect x="9" y="6" width="14" height="20" rx="2" fill="#F7F8FB"/>
      <rect x="11.5" y="10" width="9" height="2" rx="1" fill="#9AA6BA"/>
      <rect x="8" y="14.5" width="16" height="4.5" rx="1" fill="#FFD93D" opacity=".92"/>
      <rect x="11.5" y="15.5" width="9" height="2" rx="1" fill="#12213B"/>
      <rect x="11.5" y="21" width="6" height="2" rx="1" fill="#9AA6BA"/>
    </svg>
    Shortlist
  </span>
</div></header>
<main>${body}</main>
</body></html>`;

const params = $('Job Page').first().json.query || {};
const job = $('Get Job Row').first().json || {};
const esc = (s) => String(s ?? "").replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

if (!job.jobId || String(job.jobId).trim() !== String(params.jobId || "").trim()) {
  return [{ json: { html: shell("Job not found", '<div class="panel" style="max-width:640px;margin:0 auto;text-align:center;border-top-color:var(--danger)"><h1 style="font-size:28px">Job not found</h1><p class="lede" style="margin:0">This job does not exist or the link is not valid.</p></div>') } }];
}

// Both spellings are accepted, so the page works with the names in the sheet
const MANUAL = ["Needs Manual Review", "Manual Review"];
const PENDING = ["Pending Review", "Interview Scheduled"];

const jobId = String(job.jobId).trim();
const apps = $('Get Job Applicants').all().map(i => i.json).filter(a => a && a.applicationId);
const st = (name) => apps.filter(a => String(a.status).trim() === name).length;
const stInList = (names) => apps.filter(a => names.includes(String(a.status).trim())).length;

const SECTIONS = [
  { statuses: PENDING, title: "Pending review", color: "#075e4b", cols: "review",
    hint: "Passed automatic screening, or interview scheduled. Review the summary and accept the best fits." },
  { statuses: MANUAL, title: "Manual review", color: "#8a5a00", cols: "review",
    hint: "Borderline cases. Read the CV, then move to Pending review when you are ready to consider the applicant." },
  { statuses: ["Accepted", "Offer Sent"], title: "Accepted", color: "#166534", cols: "basic",
    hint: "Candidates who passed the interview and were accepted." },
  { statuses: ["Auto-Rejected"], title: "Auto-rejected", color: "#b3261e", cols: "basic",
    hint: "Rejected by automatic screening. Kept for reference." }
];
const listed = SECTIONS.flatMap(s => s.statuses);

const stat = (label, value, color) =>
  '<div><dt>' + label + '</dt><dd style="color:' + color + '">' + value + '</dd></div>';

const statsHtml = '<dl class="figures">' +
  stat("Total applicants", apps.length, "#12213b") +
  stat("Pending review", stInList(PENDING), "#075e4b") +
  stat("Manual review", stInList(MANUAL), "#8a5a00") +
  stat("Accepted", stInList(["Accepted", "Offer Sent"]), "#166534") +
  stat("Auto-rejected", st("Auto-Rejected"), "#b3261e") +
  '</dl>';

const sorted = apps.slice().sort((a, b) => (Number(b.finalScore) || 0) - (Number(a.finalScore) || 0));

const nameCell = (a) => '<div class="name">' + esc(a.applicantName) + '</div><div class="muted">' + esc(a.applicantEmail) + '</div>';
const scoreCell = (a) => '<span class="score">' + esc(a.finalScore || "—") + '</span>';
const cvCell = (a) => a.cvLink
  ? '<a class="link" href="' + esc(a.cvLink) + '" target="_blank" rel="noopener">Open CV</a>'
  : '<span class="muted">—</span>';

const row = (a, cols) => {
  const s = String(a.status).trim();
  const cells = [
    '<td>' + nameCell(a) + '</td>',
    '<td>' + esc(String(a.applicantPhone || "")) + '</td>',
    '<td>' + esc(a.appliedPosition) + '</td>',
    '<td>' + scoreCell(a) + '</td>'
  ];
  if (cols === "review") {
    cells.push('<td>' + (a.interviewDate ? esc(a.interviewDate) : '<span class="tag">Awaiting booking</span>') + '</td>');
    cells.push('<td>' + (a.meetingLink
      ? '<a class="link" href="' + esc(a.meetingLink) + '" target="_blank" rel="noopener">Join meeting</a>'
      : '<span class="muted">—</span>') + '</td>');
    cells.push('<td><div class="summary">' + esc(a.fitSummary || "—") + '</div></td>');
  }
  cells.push('<td>' + cvCell(a) + '</td>');
  if (cols === "review") {
    const buttons = [];
    if (PENDING.includes(s)) {
      buttons.push('<button class="btn" data-accept="' + esc(a.applicationId) + '">Accept</button>');
    }
    if (MANUAL.includes(s)) {
      // data-job carries the job ID to the click handler
      buttons.push('<button class="btn btn-alt" data-pending="' + esc(a.applicationId) + '" data-job="' + esc(jobId) + '">Move to pending</button>');
    }
    cells.push('<td><div class="actions">' + buttons.join('') + '</div></td>');
  }
  return '<tr>' + cells.join('') + '</tr>';
};

const headers = (cols) => cols === "review"
  ? ['Name', 'Phone', 'Applied role', 'Score', 'Interview date', 'Interview link', 'Summary', 'CV', 'Actions']
  : ['Name', 'Phone', 'Applied role', 'Score', 'CV'];

const panel = (sec, list) => {
  const cols = headers(sec.cols);
  const head = cols.map(h => '<th>' + h + '</th>').join('');
  const rows = list.length
    ? list.map(a => row(a, sec.cols)).join('')
    : '<tr><td colspan="' + cols.length + '" class="muted">No applicants in this section.</td></tr>';
  return '<section class="panel" style="--c:' + sec.color + '">' +
    '<div class="panel__head"><div class="panel__title"><span class="dot"></span><h2>' + esc(sec.title) + '</h2></div>' +
    '<div class="panel__right"><span class="count"><b>' + list.length + '</b> ' + (list.length === 1 ? 'applicant' : 'applicants') + '</span></div></div>' +
    '<p class="hint">' + esc(sec.hint) + '</p>' +
    '<div class="tablewrap"><table><thead><tr>' + head + '</tr></thead>' +
    '<tbody>' + rows + '</tbody></table></div>' +
    '</section>';
};

const mainPanels = SECTIONS
  .map(sec => {
    const list = sorted.filter(a => sec.statuses.includes(String(a.status).trim()));
    return (list.length || sec.statuses === MANUAL) ? panel(sec, list) : '';
  })
  .join('');

const other = sorted.filter(a => !listed.includes(String(a.status).trim()));
const otherPanel = other.length
  ? panel({ title: "Other", color: "#56657e", cols: "basic", hint: "Applicants with a status not listed above." }, other)
  : '';

const body = '<p class="crumb"><a href="javascript:history.back()">← Back to my jobs</a></p>' +
  '<h1>' + esc(job.role) + '</h1>' +
  '<p class="lede">Job ID <strong>' + esc(job.jobId) + '</strong> · Status <strong>' + esc(job.status) + '</strong></p>' +
  statsHtml +
  (mainPanels + otherPanel || '<div class="empty">No applicants yet.</div>') +
  '<script>' +
  'var base = location.pathname.replace(/\\/job\\/?$/, "");' +
  'var JOB = new URLSearchParams(location.search).get("jobId") || "";' +
  'async function post(path, payload){' +
  '  var r = await fetch(base + path, {method: "POST", headers: {"Content-Type": "application/json"}, body: JSON.stringify(payload)});' +
  '  return r.json();' +
  '}' +
  'document.addEventListener("click", async function(e){' +
  '  var t = e.target;' +
  '  var id = t.getAttribute("data-accept");' +
  '  var one = t.getAttribute("data-pending");' +
  '  var job = t.getAttribute("data-job");' +
  '  var jid = JOB;' +
  '  if (!id && !one) return;' +
  '  if (id && !confirm("Accept this applicant? They will receive a congratulations email.")) return;' +
  '  t.disabled = true;' +
  '  console.log(t);' +
  '  try {' +
  '    var d;' +
  '    if (id) d = await post("/accept-applicant", {applicationId: id});' +
  '    else d = await post("/applicant-to-pending", {applicationId: one, jobId: jid});' +
  '    console.log(d);' +
  '    if (d.ok) { if (id) alert("Accepted. The congratulations email is on its way."); location.reload(); }' +
  '    else { alert((d.errors || ["Something went wrong."]).join("\\n")); t.disabled = false; }' +
  '  } catch (err) { alert("Could not reach the server. Please try again."); t.disabled = false; }' +
  '});' +
  '</script>';

return [{ json: { html: shell("Job applicants", body) } }];
